/// <summary>
/// the <C>METSysOperationServiceBase</C> Class used to implement mutltithread for batch jobs
/// </summary>
abstract class METSysOperationServiceBase extends SysOperationServiceBase
{
    BatchHeader                             batchHeader;
    METSysOperationServiceBaseDataContract  dataContract;

}

Method.Source:
/// <summary>
/// method used for triggering the class functionality.
/// </summary>
/// <param name = "_dataContract">data contract</param>
public void run(METSysOperationServiceBaseDataContract _dataContract)
{
    try
    {
        this.init(_dataContract);
        this.process();
        this.finalize();
    }
    catch
    {
        warning("@ApplicationPlatform:SystemNotificationSeverity_Error");
        info(con2Str(xSession::xppCallStack()));
    }
}

/// <summary>
/// method used to initilize values.
/// </summary>
/// <param name = "_dataContract">base data contract object</param>
protected void init(METSysOperationServiceBaseDataContract _dataContract)
{
    dataContract = _dataContract;
    this.initBatch();
}

/// <summary>
/// method needs to be overridden in child class to put caption for the batch job.
/// </summary>
/// <returns>Description</returns>
protected abstract Description getCaption()
{
    // must override method to specify caption for the batch job.
}

/// <summary>
/// method used to initialize the batch job.
/// </summary>
protected void initBatch()
{
    if(!batchHeader)// && this.isExecutingInBatch())
    {
        batchHeader = BatchHeader::construct();//this.getCurrentBatchHeader();
    }
}

/// <summary>
/// method used to construct controller and data contract.
/// </summary>
/// <returns>controller object</returns>
protected abstract SysOperationServiceController constructTask()
{
    // must override & put the required logic.
}

/// <summary>
/// method used to invoke batch job.
/// </summary>
protected void invoke()
{
    this.initBatch();
    SysOperationServiceController controller = this.constructTask();
    this.invokeTask(controller);
}

/// <summary>
/// method used to invoke runtime task for a batch job.
/// </summary>
/// <param name = "_controller">service controller object</param>
protected void invokeTask(SysOperationServiceController _controller)
{
    //if(this.isExecutingInBatch())
    //{
        // code is running in batch, so add a runtime task
        _controller.batchInfo().parmCaption(this.getCaption());
        batchHeader.addTask(_controller);//, this.getCurrentBatchTask().RecId);
    //}
    //else
    //{
    //    _controller.run();
    //}
}

/// <summary>
/// method used to do the main processing and calling the invoke method.
/// </summary>
protected abstract void process()
{
    // must override & put the required logic.
    // call the invoke method.
}

/// <summary>
/// method used to save the batch header.
/// </summary>
public void finalize()
{
    if (this.isExecutingInBatch() && batchHeader)
    {
        batchHeader.save();
    }

    xApplication::checkForNewBatchJobs();
}
